        refresh_lockfiles: false,
        transient: false,
    };

    let result = apply_version_plan(ws_dir.path(), &plan, &runner, &opts, &ApplyPermit::force_for_tests());

    assert!(
        result.is_err(),
        "expected apply_version_plan to return an error when `git add` fails, got: {result:?}"
    );
}
